**Approach:** One-pass hash map — for each `num`, check if `target - num` was seen. O(n) time, O(n) space. Handles negatives, duplicates.

**Key steps:** map stores `value -> index`. On iteration, compute complement and test `has`.

```javascript
function twoSum(nums, target) {
  const map = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (map.has(need)) return [map.get(need), i];
    map.set(nums[i], i);
  }
  return [];
}

// Runnable demo
console.log(twoSum([2,7,11,15], 9)); // [0,1]
console.log(twoSum([3,2,4], 6)); // [1,2]
console.log(twoSum([3,3], 6)); // [0,1]
console.log(twoSum([-1, -2, -3, -4], -6)); // [1,3]
```
Edge: return `[]` if not found. Variant: return values not indices — same map but store complement check first.

**Approach:** Closure holds timer + last args. On call, clear previous timer and schedule new. Leading fires immediately if not already waiting; trailing fires after quiet period. `cancel` clears timer, `flush` invokes pending immediately.

```javascript
function debounce(func, wait, { leading = false, trailing = true } = {}) {
  let timer = null, lastArgs, lastThis, result;
  let pending = false;
  function invoke() {
    result = func.apply(lastThis, lastArgs);
    lastArgs = lastThis = null;
    pending = false;
    return result;
  }
  function debounced(...args) {
    lastArgs = args; lastThis = this; pending = true;
    const shouldLead = leading && !timer;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (trailing && pending) invoke();
      else pending = false;
    }, wait);
    if (shouldLead) return invoke();
    return result;
  }
  debounced.cancel = () => { clearTimeout(timer); timer = null; pending = false; lastArgs = lastThis = null; };
  debounced.flush = () => { if (pending) { clearTimeout(timer); timer = null; return invoke(); } };
  return debounced;
}

// Demo
const log = debounce((v) => console.log('call', v), 200);
log(1); log(2); log(3); // only 3 after 200ms
setTimeout(() => log.flush(), 100); // forces immediate
const leading = debounce(console.log, 200, { leading: true, trailing: false });
leading('a'); leading('b'); // 'a' immediately, 'b' ignored
```
Use `AbortController` variant for fetch debouncing in React.

**Approach:** Map cache keyed by resolver or JSON.stringify. On hit return cached; on miss compute, set, and evict if over maxSize. Expose `cache` Map.

```javascript
function memoize(func, resolver, maxSize = Infinity) {
  const cache = new Map();
  function memoized(...args) {
    const key = resolver ? resolver(...args) : JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = func.apply(this, args);
    if (cache.size >= maxSize) {
      const firstKey = cache.keys().next().value;
      cache.delete(firstKey);
    }
    cache.set(key, result);
    return result;
  }
  memoized.cache = cache;
  memoized.clear = () => cache.clear();
  return memoized;
}

// Demo
const add = memoize((a,b) => { console.log('compute', a,b); return a+b; });
console.log(add(1,2)); // compute 1 2 -> 3
console.log(add(1,2)); // cached 3 (no log)
console.log(add(2,3)); // compute 2 3 -> 5
const fetchUser = memoize((id, opts) => ({id}), (id) => String(id));
console.log(fetchUser(1, {a:1}));
console.log(fetchUser(1, {a:2})); // cache hit on id '1'
```
For object keys, use `WeakMap` or custom Map with `Map` + deep key.

**Approach:** Map `event -> Set<listener>`. `once` wraps listener to self-remove after first call. `emit` clones listeners before iterating to allow mutation during emit.

```javascript
class EventEmitter {
  constructor() { this.events = new Map(); }
  on(event, listener) {
    if (!this.events.has(event)) this.events.set(event, new Set());
    this.events.get(event).add(listener);
    return this;
  }
  off(event, listener) {
    if (!this.events.has(event)) return this;
    if (!listener) this.events.delete(event);
    else this.events.get(event).delete(listener);
    return this;
  }
  once(event, listener) {
    const wrapper = (...args) => { this.off(event, wrapper); listener(...args); };
    wrapper._original = listener;
    return this.on(event, wrapper);
  }
  emit(event, ...args) {
    const set = this.events.get(event);
    if (!set) return false;
    for (const fn of [...set]) fn(...args);
    return true;
  }
  removeAllListeners(event) {
    if (event) this.events.delete(event);
    else this.events.clear();
    return this;
  }
  listenerCount(event) { return this.events.get(event)?.size ?? 0; }
}

// Demo
const ee = new EventEmitter();
ee.on('data', x => console.log('on', x));
ee.once('data', x => console.log('once', x));
ee.emit('data', 1); // on 1, once 1
ee.emit('data', 2); // on 2
console.log(ee.listenerCount('data')); // 1
ee.off('data');
console.log(ee.emit('data', 3)); // false
```
Edge: `once` removal must work even if `off` called with original fn — store `_original` and compare.

**Approach:** Queue + active count. `limit(fn)` enqueues and tries to run. `runNext` dequeues if `active < concurrency`, increments active, awaits fn, then decrements and recurses.

```javascript
function pLimit(concurrency) {
  let active = 0;
  const queue = [];
  const next = () => {
    if (active >= concurrency || queue.length === 0) return;
    active++;
    const { fn, resolve, reject } = queue.shift();
    (async () => fn())().then(resolve, reject).finally(() => { active--; next(); });
  };
  return function limit(fn) {
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      next();
    });
  };
}

// Demo
const limit = pLimit(2);
const sleep = (ms, v) => new Promise(r => setTimeout(() => r(v), ms));
async function demo() {
  const start = Date.now();
  const tasks = [1,2,3,4].map(i => limit(() => sleep(200, i).then(v => {
    console.log(`task ${v} done at ${Date.now()-start}ms`); return v;
  })));
  console.log(await Promise.all(tasks)); // [1,2,3,4], but only 2 at a time
}
demo();
```
Handles rejection without stalling queue (finally triggers next).

**Approach:** Fast paths for SameValue (Object.is distinguishes -0/NaN), then type checks, then structural recursion with WeakMap for circular tracking.

```javascript
function deepEqual(a, b, seen = new WeakMap()) {
  if (Object.is(a, b)) return true;
  if (a == null || b == null || typeof a !== 'object' || typeof b !== 'object') return false;
  if (seen.has(a)) return seen.get(a) === b;
  seen.set(a, b);
  const protoA = Object.getPrototypeOf(a), protoB = Object.getPrototypeOf(b);
  if (protoA !== protoB) return false;
  if (a instanceof Date) return a.getTime() === b.getTime();
  if (a instanceof RegExp) return String(a) === String(b);
  if (a instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [k,v] of a) if (!b.has(k) || !deepEqual(v, b.get(k), seen)) return false;
    return true;
  }
  if (a instanceof Set) {
    if (a.size !== b.size) return false;
    for (const v of a) if (!b.has(v)) return false;
    return true;
  }
  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    return a.every((v,i) => deepEqual(v, b[i], seen));
  }
  const keysA = Reflect.ownKeys(a), keysB = Reflect.ownKeys(b);
  if (keysA.length !== keysB.length) return false;
  return keysA.every(k => keysB.includes(k) && deepEqual(a[k], b[k], seen));
}

// Demo
console.log(deepEqual(NaN, NaN)); // true
console.log(deepEqual(0, -0)); // false (Object.is)
console.log(deepEqual({a:1, b:[2]}, {a:1, b:[2]})); // true
console.log(deepEqual(new Date('2020-01-01'), new Date('2020-01-01'))); // true
console.log(deepEqual(/ab/gi, /ab/gi)); // true
const c = {}; c.self = c; const d = {}; d.self = d;
console.log(deepEqual(c, d)); // true (circular)
console.log(deepEqual({a: NaN}, {a: NaN})); // true
```
Note: lodash `isEqual` uses `===` for -0 (treats 0 === -0); pick behavior and document.

**Approach:** Track `lastCall` time + trailing timer. Leading invokes immediately if elapsed >= wait; trailing schedules last args.

```javascript
function throttle(func, wait, { leading = true, trailing = true } = {}) {
  let lastCall = 0, timer = null, lastArgs, lastThis, result;
  function invoke(time) {
    lastCall = time;
    result = func.apply(lastThis, lastArgs);
    lastArgs = lastThis = null;
    return result;
  }
  function throttled(...args) {
    const now = Date.now();
    const remaining = wait - (now - lastCall);
    lastArgs = args; lastThis = this;
    if (remaining <= 0 || remaining > wait) {
      if (timer) { clearTimeout(timer); timer = null; }
      if (leading) return invoke(now);
    }
    if (!timer && trailing) {
      timer = setTimeout(() => {
        timer = null;
        if (trailing && lastArgs) invoke(Date.now());
      }, remaining > 0 ? remaining : wait);
    }
    return result;
  }
  throttled.cancel = () => { clearTimeout(timer); timer = null; lastArgs = lastThis = null; };
  throttled.flush = () => { if (timer) { clearTimeout(timer); timer = null; if (lastArgs) return invoke(Date.now()); } };
  return throttled;
}

// Demo
let count = 0;
const inc = throttle(() => count++, 100, { leading: true, trailing: true });
inc(); inc(); inc(); // leading immediate count=1
setTimeout(() => { inc(); console.log(count); }, 150);
```
Difference vs debounce: throttle guarantees periodic execution during continuous calls.

**Approach:** Accumulate args until arity met; placeholder version needs gap filling. Simple version covers 90% of interviews; placeholder extended is bonus.

```javascript
function simpleCurry(fn, arity = fn.length) {
  return function curried(...args) {
    if (args.length >= arity) return fn.apply(this, args);
    return (...next) => curried.apply(this, [...args, ...next]);
  };
}
curryPlaceholder.placeholder = Symbol('_');
function curryPlaceholder(fn, arity = fn.length) {
  const PH = curryPlaceholder.placeholder;
  function curried(...args) {
    const prev = curried._prev || [];
    const all = [...prev, ...args];
    const real = all.filter(v => v !== PH).length;
    if (real >= arity) {
      const out=[]; let j=0;
      for(let i=0;i<all.length && out.length < arity;i++){
        if(all[i]===PH){ while(j<args.length && args[j]===PH) j++; if(j<args.length) out.push(args[j++]); }
        else out.push(all[i]);
      }
      if(out.includes(PH)) { const n=curryPlaceholder(fn, arity); n._prev=out; return n; }
      return fn.apply(this, out.slice(0, arity));
    }
    const n=curryPlaceholder(fn, arity); n._prev=all; return n;
  }
  curried._prev=[]; return curried;
}

// Demo
function add(a,b,c) { return a+b+c; }
const curried = simpleCurry(add);
console.log(curried(1)(2)(3)); // 6
console.log(curried(1,2)(3)); // 6
console.log(curried(1)(2,3)); // 6
console.log(simpleCurry((a,b)=>a*b)(2)(3)); // 6
```
