  if (fns.length === 0) return x => x;
  return function(...args) {
    let result = fns[fns.length - 1].apply(this, args);
    for (let i = fns.length - 2; i >= 0; i--) result = fns[i].call(this, result);
    return result;
  };
}
function pipe(...fns) {
  if (fns.length === 0) return x => x;
  return function(...args) {
    let result = fns[0].apply(this, args);
    for (let i = 1; i < fns.length; i++) result = fns[i].call(this, result);
    return result;
  };
}
function pipeAsync(...fns) {
  return async function(...args) {
    let res = await fns[0].apply(this, args);
    for (let i = 1; i < fns.length; i++) res = await fns[i].call(this, res);
    return res;
  };
}

