    const exists = this.map.has(key);
    if (exists) clearTimeout(this.map.get(key).timer);
    const timer = setTimeout(() => this.map.delete(key), duration);
    this.map.set(key, { value, timer });
    return exists;
  }
  get(key) { return this.map.has(key) ? this.map.get(key).value : -1; }
  count() { return this.map.size; }
}

