      const nextIsArrayIndex = !isLast && /^\\d+$/.test(keys[i+1]);
      if (isLast) cur[k] = val;
      else { if (!(k in cur)) cur[k] = nextIsArrayIndex ? [] : {}; cur = cur[k]; }
    }
  }
  return res;
}

