  const sleep = (ms, v) => () => new Promise(r => setTimeout(()=>r(v), ms));
  const results = await Promise.all([q.add(sleep(50,1)), q.add(sleep(30,2)), q.add(sleep(20,3))]);
  console.log(results); // [1,2,3]
  await q.onIdle();
