**Approach:** States pending/fulfilled/rejected; queue handlers; `resolvePromise` handles thenables recursively; `then` returns new promise.

```javascript
class MyPromise {
  constructor(executor) {
    this.state = 'pending'; this.value = undefined; this.handlers = [];
    const resolve = (v) => this._resolve(v);
    const reject = (r) => this._reject(r);
    try { executor(resolve, reject); } catch(e) { reject(e); }
  }
  _resolve(v) {
    if (this.state !== 'pending') return;
    if (v && (typeof v === 'object' || typeof v === 'function') && typeof v.then === 'function') {
      try { v.then(this._resolve.bind(this), this._reject.bind(this)); } catch(e){ this._reject(e); }
      return;
    }
    this.state = 'fulfilled'; this.value = v;
    this.handlers.forEach(h => this._handle(h));
  }
  _reject(r) {
    if (this.state !== 'pending') return;
    this.state = 'rejected'; this.value = r;
    this.handlers.forEach(h => this._handle(h));
  }
  _handle(handler) {
    if (this.state === 'pending') { this.handlers.push(handler); return; }
    queueMicrotask(() => {
      const cb = this.state === 'fulfilled' ? handler.onFulfilled : handler.onRejected;
      if (!cb) { (this.state === 'fulfilled' ? handler.resolve : handler.reject)(this.value); return; }
      try { handler.resolve(cb(this.value)); } catch(e){ handler.reject(e); }
    });
  }
  then(onFulfilled, onRejected) {
    return new MyPromise((resolve, reject) => { this._handle({ onFulfilled, onRejected, resolve, reject }); });
  }
  catch(onRejected){ return this.then(null, onRejected); }
  static resolve(v){ return new MyPromise(r=>r(v)); }
  static reject(e){ return new MyPromise((_,r)=>r(e)); }
}

// Demo
