Used for pagination, calendar grids, test data.

**Approach:** Split path to keys, walk/create intermediate objects or arrays (numeric key -> array). Final key set.

```javascript
function set(obj, path, value) {
  const keys = Array.isArray(path) ? path : path.replace(/\[(\w+)\]/g, '.$1').split('.').filter(Boolean);
  let cur = obj;
  for (let i=0; i<keys.length; i++) {
    const k = keys[i];
    if (i === keys.length - 1) cur[k] = value;
    else {
      if (cur[k] == null || typeof cur[k] !== 'object') {
        const nextIsIndex = /^\\d+$/.test(keys[i+1]);
        cur[k] = nextIsIndex ? [] : {};
      }
      cur = cur[k];
    }
  }
  return obj;
}

// Demo
const o = {};
set(o, 'a.b[0].c', 42);
console.log(JSON.stringify(o)); // {"a":{"b":[{"c":42}]}}
console.log(set({a:{b:1}}, 'a.b', 2)); // {a:{b:2}}
console.log(set({}, ['x','y',0], 'hi')); // {x:{y:['hi']}}
console.log(set({a:[]}, 'a[1].b', 5)); // {a:[undefined,{b:5}]}
```
Companion to `get`; handle array indices by checking if next key is numeric.

**Approach:** Loop by index, check `i in O` for sparse, test callback, push if truthy.

```javascript
Array.prototype.myFilter = function(callback, thisArg) {
  if (this == null) throw new TypeError('myFilter called on null');
  if (typeof callback !== 'function') throw new TypeError(callback + ' is not a function');
  const O = Object(this);
  const len = O.length >>> 0;
  const res = [];
  for (let i=0; i<len; i++) {
    if (i in O) {
      const val = O[i];
      if (callback.call(thisArg, val, i, O)) res.push(val);
    }
  }
  return res;
};

// Demo
console.log([1,2,3,4].myFilter(x => x%2===0)); // [2,4]
console.log([1,,3,4].myFilter(x => x>1)); // [3,4] (hole skipped)
console.log([1,2,3].myFilter(function(x){ return x > this.min }, {min:2})); // [3]
console.log(Array.prototype.myFilter.call({0:'a',1:'b',2:'c',length:2}, x=>x!=='a')); // ['b']
console.log([0,1,false,2].myFilter(Boolean)); // [1,2]
```
Spec: does not mutate, skips holes, passes (value, index, array) and honors thisArg.
